import { useState } from 'react';
import { Screen, Card, Stack, Alert, TextField, Button, KeyBar } from '@nexti/ds';

const MONTO_MIN = 1000;
const MONTO_MAX = 50000;
const PLAZO_MIN = 6;
const PLAZO_MAX = 60;

const MSG_MONTO = 'El monto debe estar entre 1.000 y 50.000';
const MSG_PLAZO = 'El plazo debe estar entre 6 y 60 meses';

function toText(v: unknown): string {
  if (typeof v === 'string') return v;
  const anyV = v as { target?: { value?: string } } | null | undefined;
  return anyV?.target?.value ?? '';
}

function parseMonto(raw: string): number | null {
  const s = raw.trim().replace(/\s/g, '');
  if (!s) return null;
  let normalized = s;
  if (s.includes(',')) {
    // formato es: 1.234,56
    normalized = s.replace(/\./g, '').replace(',', '.');
  } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    // 1.000 / 50.000 (separador de miles)
    normalized = s.replace(/\./g, '');
  }
  if (!/^\d+(\.\d{1,2})?$/.test(normalized)) return null;
  return Number(normalized);
}

function validateMonto(raw: string): string | undefined {
  const n = parseMonto(raw);
  if (n === null || n < MONTO_MIN || n > MONTO_MAX) return MSG_MONTO;
  return undefined;
}

function validatePlazo(raw: string): string | undefined {
  const s = raw.trim();
  if (!/^\d+$/.test(s)) return MSG_PLAZO;
  const n = Number(s);
  if (n < PLAZO_MIN || n > PLAZO_MAX) return MSG_PLAZO;
  return undefined;
}

export default function Simulador({ navigate }: { navigate: (to: string) => void }) {
  const [monto, setMonto] = useState('');
  const [plazo, setPlazo] = useState('');
  const [errors, setErrors] = useState<{ monto?: string; plazo?: string }>({});
  const [submitted, setSubmitted] = useState(false);

  const isEmpty = monto === '' && plazo === '' && !submitted;
  const hasErrors = Boolean(errors.monto || errors.plazo);

  const calcular = () => {
    const next = { monto: validateMonto(monto), plazo: validatePlazo(plazo) };
    setErrors(next);
    setSubmitted(true);
    if (!next.monto && !next.plazo) {
      navigate('SCR-RESULTADO');
    }
  };

  return (
    <Screen
      title="Simulador"
      code="SCR-SIMULADOR"
      keys={<KeyBar actions={[{ key: 'ENTER', label: 'Calcular', onPress: calcular, primary: true }]} />}
    >
      <div
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            calcular();
          }
        }}
      >
        <Card
          title="Simula tu crédito de consumo"
          actions={
            <Button variant="primary" shortcut="ENTER" onClick={calcular}>
              Calcular
            </Button>
          }
        >
          <Stack>
            {isEmpty && (
              <Alert tone="info">
                Ingresa el monto y el plazo para simular tu crédito de consumo.
              </Alert>
            )}
            {submitted && hasErrors && (
              <Alert tone="error">
                Revisa los campos marcados antes de continuar.
              </Alert>
            )}

            <div data-field="monto">
              <TextField
                label="Monto (USD)"
                required
                numeric
                maxLength={12}
                hint="Entre 1.000 y 50.000"
                error={errors.monto}
                value={monto}
                onChange={(v: unknown) => {
                  setMonto(toText(v));
                  if (submitted) setErrors((e) => ({ ...e, monto: undefined }));
                }}
              />
            </div>

            <div data-field="plazo">
              <TextField
                label="Plazo (meses)"
                required
                numeric
                maxLength={10}
                hint="Entre 6 y 60 meses"
                error={errors.plazo}
                value={plazo}
                onChange={(v: unknown) => {
                  setPlazo(toText(v));
                  if (submitted) setErrors((e) => ({ ...e, plazo: undefined }));
                }}
              />
            </div>
          </Stack>
        </Card>
      </div>
    </Screen>
  );
}
