import { useState } from 'react'
import type { FormEvent } from 'react'
import { Screen, Card, Stack, TextField, Button, Alert } from '@nexti/ds'
import { ApiError } from '../api/client'
import type { ScreenProps } from './types'

const MSG_MONTO_REQUIRED = 'El monto es obligatorio'
const MSG_PLAZO_REQUIRED = 'El plazo es obligatorio'
const MSG_MONTO_FORMAT = 'Ingresa un monto numérico válido'
const MSG_PLAZO_FORMAT = 'Ingresa un plazo en meses enteros'

function toText(v: unknown): string {
  if (typeof v === 'string') return v
  const anyV = v as { target?: { value?: string } } | null | undefined
  return anyV?.target?.value ?? ''
}

function parseMonto(raw: string): number | null {
  const s = raw.trim().replace(/\s/g, '')
  if (!s) return null
  let normalized = s
  if (s.includes(',')) {
    normalized = s.replace(/\./g, '').replace(',', '.')
  } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    normalized = s.replace(/\./g, '')
  }
  if (!/^\d+(\.\d{1,2})?$/.test(normalized)) return null
  return Number(normalized)
}

function parsePlazo(raw: string): number | null {
  const s = raw.trim()
  if (!/^\d+$/.test(s)) return null
  return Number(s)
}

function formatMoney(n: number): string {
  return n.toFixed(2)
}

export default function SimuladorScreen({ api }: ScreenProps) {
  const [monto, setMonto] = useState('')
  const [plazo, setPlazo] = useState('')
  const [errors, setErrors] = useState<{ monto?: string; plazo?: string }>({})
  const [message, setMessage] = useState<string | null>(null)
  const [result, setResult] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)

  const submit = async (e?: FormEvent) => {
    e?.preventDefault()
    setMessage(null)
    setResult(null)

    const next: { monto?: string; plazo?: string } = {}
    if (monto.trim() === '') next.monto = MSG_MONTO_REQUIRED
    if (plazo.trim() === '') next.plazo = MSG_PLAZO_REQUIRED
    if (next.monto || next.plazo) {
      setErrors(next)
      return
    }

    const montoNum = parseMonto(monto)
    const plazoNum = parsePlazo(plazo)
    if (montoNum === null) next.monto = MSG_MONTO_FORMAT
    if (plazoNum === null) next.plazo = MSG_PLAZO_FORMAT
    if (next.monto || next.plazo || montoNum === null || plazoNum === null) {
      setErrors(next)
      return
    }

    setErrors({})
    setBusy(true)
    try {
      const res = await api.simulateConsumerLoan({ monto: montoNum, plazo: plazoNum })
      setResult(
        `Tasa anual: ${formatMoney(res.tasaAnual)} % · Cuota mensual: ${formatMoney(res.cuotaMensual)} · Total a pagar: ${formatMoney(res.totalAPagar)}`,
      )
    } catch (err) {
      if (err instanceof ApiError) {
        setMessage(err.message)
      } else {
        setMessage('No se pudo calcular la simulación')
      }
    } finally {
      setBusy(false)
    }
  }

  return (
    <Screen title="Simulador">
      <form onSubmit={submit} noValidate>
        <Card title="Simula tu crédito de consumo">
          <Stack>
            {message && <Alert tone="error">{message}</Alert>}
            {result && <Alert tone="info">{result}</Alert>}

            <div data-field="monto">
              <TextField
                label="Monto (USD)"
                required
                numeric
                hint="Entre 1.000 y 50.000"
                error={errors.monto}
                value={monto}
                onChange={(v: unknown) => {
                  setMonto(toText(v))
                  setErrors((prev) => ({ ...prev, monto: undefined }))
                }}
              />
            </div>

            <div data-field="plazo">
              <TextField
                label="Plazo (meses)"
                required
                numeric
                hint="Entre 6 y 60 meses"
                error={errors.plazo}
                value={plazo}
                onChange={(v: unknown) => {
                  setPlazo(toText(v))
                  setErrors((prev) => ({ ...prev, plazo: undefined }))
                }}
              />
            </div>

            <Button type="submit" variant="primary" data-action="ENTER" disabled={busy}>
              Calcular
            </Button>
          </Stack>
        </Card>
      </form>
    </Screen>
  )
}
